<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="robots" content="noindex,nofollow"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Blog CMS | Amity Online</title><link rel="stylesheet" href="css/styles.css"><style>
body{background:#f4f6fa}.cms-shell{max-width:1400px;margin:auto;padding:2rem}.cms-top{display:flex;justify-content:space-between;align-items:center;gap:1rem;margin-bottom:2rem}.cms-stats,.cms-grid{display:grid;grid-template-columns:repeat(6,1fr);gap:1rem}.cms-card,.cms-panel{background:#fff;border:1px solid #e2e7ef;border-radius:8px;padding:1rem}.cms-card strong{display:block;font-size:1.8rem;color:#0a2e73}.cms-toolbar{display:flex;gap:.6rem;flex-wrap:wrap;margin:1rem 0}.cms-toolbar input,.cms-toolbar select,.cms-form input,.cms-form textarea,.cms-form select{padding:.7rem;border:1px solid #ccd3df;border-radius:5px}.cms-toolbar input{flex:1;min-width:220px}.cms-table{width:100%;border-collapse:collapse}.cms-table th,.cms-table td{padding:.8rem;text-align:left;border-bottom:1px solid #edf0f5;vertical-align:top}.cms-table th{font-size:.78rem;text-transform:uppercase;color:#667085}.pill{padding:.25rem .5rem;border-radius:99px;background:#eef2f7;font-size:.78rem}.pill.published{background:#d1fadf;color:#067647}.pill.draft{background:#f2f4f7}.pill.pending{background:#fef0c7;color:#b54708}.cms-editor{display:none;grid-template-columns:minmax(0,1fr) 320px;gap:1rem}.cms-editor.active{display:grid}.cms-form{display:grid;gap:.8rem}.cms-form label{display:grid;gap:.3rem;font-weight:600}.cms-form textarea{min-height:180px;font:inherit}.cms-form small{font-weight:400;color:#667085}.cms-actions{display:flex;gap:.5rem;flex-wrap:wrap}.seo-list{list-style:none;padding:0}.seo-list li{padding:.45rem 0;border-bottom:1px solid #edf0f5}.good{color:#067647}.warn{color:#b54708}.bad{color:#b42318}@media(max-width:900px){.cms-stats{grid-template-columns:repeat(3,1fr)}.cms-editor.active{grid-template-columns:1fr}.cms-table{display:block;overflow:auto;white-space:nowrap}}@media(max-width:560px){.cms-shell{padding:1rem}.cms-stats{grid-template-columns:repeat(2,1fr)}}
</style></head><body><main class="cms-shell"><header class="cms-top"><div><p class="eyebrow">AMITY ONLINE</p><h1>Blog management</h1></div><div class="cms-actions"><button class="btn btn-primary" id="newBlog">New blog</button><button class="btn btn-outline" id="logout">Sign out</button></div></header><section class="cms-stats" id="stats"></section><section class="cms-panel"><div class="cms-toolbar"><input id="search" placeholder="Search title, slug or keyword"><select id="status"><option value="">All statuses</option><option>draft</option><option>pending</option><option>published</option><option>scheduled</option><option>archived</option></select><button class="btn btn-outline" id="refresh">Refresh</button></div><div id="table"></div></section><section class="cms-editor" id="editor"><form class="cms-panel cms-form" id="blogForm"><h2 id="editorTitle">New blog</h2><input type="hidden" name="id"><label>Blog title <small>Maximum 70 characters</small><input name="title" maxlength="70" required></label><label>Excerpt <small>Maximum 250 characters</small><textarea name="excerpt" maxlength="250" required></textarea></label><label>URL slug<input name="slug" required></label><label>Primary keyword<input name="primary_keyword" required></label><label>Meta title <small>Recommended: 60 characters</small><input name="meta_title" maxlength="160" required></label><label>Meta description <small>Recommended: 200-250 characters</small><textarea name="meta_description" maxlength="320" required></textarea></label><label>Feature image URL<input name="feature_image" type="url"></label><label>Feature image alt text<input name="feature_image_alt" required></label><label>Content HTML <small>Only safe semantic HTML is stored. Use H2-H4 for article sections.</small><textarea name="content" required placeholder="&lt;h2&gt;First section&lt;/h2&gt;&lt;p&gt;...&lt;/p&gt;"></textarea></label><label>Status<select name="status"><option value="draft">Draft</option><option value="pending">Pending review</option><option value="published">Published</option><option value="scheduled">Scheduled</option><option value="archived">Archived</option></select></label><label>Scheduled at <input name="scheduled_at" type="datetime-local"></label><label><span><input name="toc_enabled" type="checkbox" checked> Enable table of contents</span></label><label><span><input name="lead_form_enabled" type="checkbox" checked> Enable course enquiry form</span></label><div class="cms-actions"><button class="btn btn-primary">Save blog</button><button type="button" class="btn btn-outline" id="cancelEdit">Cancel</button></div><p id="formMessage"></p></form><aside class="cms-panel"><h2>SEO checklist</h2><ul class="seo-list" id="seoList"></ul><p><a href="blog.php" target="_blank" rel="noopener">Open public blog</a></p></aside></section></main><script>
const csrf=<?php echo json_encode($csrf); ?>, form=document.getElementById('blogForm'), editor=document.getElementById('editor');
const ctaFields=document.createElement('fieldset'); ctaFields.innerHTML='<legend>Lead CTA</legend><label>CTA headline<input name="lead_form_headline" value="Talk to an admissions advisor" maxlength="160"></label><label>CTA button text<input name="lead_form_button" value="Request information" maxlength="80"></label>'; form.insertBefore(ctaFields, form.querySelector('.cms-actions'));
const faqFields=document.createElement('fieldset'); faqFields.innerHTML='<legend>FAQs</legend><div id="faqItems"></div><button type="button" class="btn btn-outline" id="addFaq">Add FAQ</button>'; form.insertBefore(faqFields, form.querySelector('.cms-actions'));
function addFaq(item={question:'',answer:''}){const row=document.createElement('div');row.className='faq-row';row.innerHTML='<input class="faq-question" placeholder="Question" value="'+esc(item.question)+'"><textarea class="faq-answer" placeholder="Answer">'+esc(item.answer)+'</textarea><button type="button">Remove</button>';row.querySelector('button').onclick=()=>row.remove();document.getElementById('faqItems').appendChild(row)} document.getElementById('addFaq').onclick=()=>addFaq();
const faqPayload=document.createElement('input');faqPayload.type='hidden';faqPayload.name='faq';form.appendChild(faqPayload);form.addEventListener('submit',()=>{syncContent();faqPayload.value=JSON.stringify([...document.querySelectorAll('.faq-row')].map(row=>({question:row.querySelector('.faq-question').value.trim(),answer:row.querySelector('.faq-answer').value.trim()})).filter(item=>item.question&&item.answer))},true);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
async function api(action,options={}){options.headers={...(options.headers||{}),'X-CSRF-Token':csrf};const r=await fetch('blog-api.php?action='+action,options);return r.json()}
const contentInput=form.elements.content;contentInput.style.display='none';contentInput.required=false;const contentEditor=document.createElement('div');contentEditor.contentEditable='true';contentEditor.className='visual-editor';contentEditor.innerHTML='<p>Start writing your article here...</p>';const contentTools=document.createElement('div');contentTools.className='content-tools';contentTools.innerHTML='<button type="button" data-command="formatBlock" data-value="p">Paragraph</button><button type="button" data-command="formatBlock" data-value="h2">H2</button><button type="button" data-command="formatBlock" data-value="h3">H3</button><button type="button" data-command="bold"><strong>B</strong></button><button type="button" data-command="italic"><em>I</em></button><button type="button" data-command="insertUnorderedList">Bullet list</button><button type="button" data-command="insertOrderedList">Numbered list</button><button type="button" data-command="formatBlock" data-value="blockquote">Quote</button><button type="button" data-command="createLink">Link</button><button type="button" data-command="undo">Undo</button><button type="button" data-command="redo">Redo</button>';contentInput.parentElement.insertBefore(contentTools,contentInput);contentInput.parentElement.insertBefore(contentEditor,contentInput);contentTools.querySelectorAll('button').forEach(button=>button.onclick=()=>{contentEditor.focus();if(button.dataset.command==='createLink'){const url=prompt('Enter a safe link URL');if(url)document.execCommand('createLink',false,url)}else document.execCommand(button.dataset.command,false,button.dataset.value||null);syncContent()});function syncContent(){contentInput.value=contentEditor.innerHTML;contentInput.dispatchEvent(new Event('input',{bubbles:true}))}contentEditor.oninput=syncContent;
newBlog.addEventListener('click',()=>{contentEditor.innerHTML='<p>Start writing your article here...</p>';syncContent();document.getElementById('faqItems').innerHTML=''});
const visualStyle=document.createElement('style');visualStyle.textContent='.content-tools{display:flex;gap:.35rem;flex-wrap:wrap;margin-top:.5rem}.content-tools button{padding:.45rem .65rem;border:1px solid #ccd3df;background:#fff;border-radius:4px;cursor:pointer}.visual-editor{min-height:280px;padding:1rem;border:1px solid #ccd3df;border-radius:5px;background:#fff;line-height:1.7}.visual-editor:focus{outline:2px solid #0a2e73;outline-offset:1px}.visual-editor blockquote{border-left:3px solid #ffcc00;padding-left:1rem;color:#667085}';document.head.appendChild(visualStyle);
const dashboardStyle=document.createElement('style');dashboardStyle.textContent='.cms-shell{color:#172033;font-family:var(--font-body,Arial,sans-serif)}.cms-top{background:linear-gradient(135deg,#0a2e73,#174a9c);color:#fff;padding:1.6rem 2rem;border-radius:12px;box-shadow:0 10px 25px rgba(10,46,115,.16)}.cms-top h1{color:#fff;margin:.15rem 0 0}.cms-top .eyebrow{color:#b9d7ff;letter-spacing:.12em;font-size:.72rem;margin:0}.cms-top .btn-outline{border-color:#fff;color:#fff}.cms-stats{margin:1.2rem 0}.cms-card{box-shadow:0 4px 14px rgba(20,42,77,.06);border:0;border-top:3px solid #ffcc00}.cms-card small{text-transform:uppercase;letter-spacing:.05em;color:#667085}.cms-panel{box-shadow:0 5px 18px rgba(20,42,77,.06)}.cms-toolbar{padding-bottom:1rem;border-bottom:1px solid #edf0f5}.cms-toolbar input,.cms-toolbar select{background:#fbfcfe}.cms-table th{background:#f7f9fc}.cms-table tr:hover td{background:#fbfdff}.cms-table button{border:0;background:none;color:#0a2e73;cursor:pointer;font-weight:600;margin:.15rem}.cms-table button[data-delete]{color:#b42318}.cms-editor{margin-top:1.2rem}.cms-editor h2{margin-top:0}.cms-form fieldset{border:1px solid #e2e7ef;border-radius:8px;padding:1rem;display:grid;gap:.7rem}.cms-form legend{color:#0a2e73;font-weight:700;padding:0 .35rem}.faq-row{display:grid;grid-template-columns:1fr 1.5fr auto;gap:.5rem;align-items:start}.faq-row button{border:0;background:#fff0f0;color:#b42318;padding:.55rem;border-radius:5px;cursor:pointer}@media(max-width:700px){.cms-top{padding:1.2rem}.faq-row{grid-template-columns:1fr}.faq-row button{justify-self:start}}';document.head.appendChild(dashboardStyle);
function refresh(){api('list&q='+encodeURIComponent(search.value)+'&status='+encodeURIComponent(status.value)).then(d=>{const blogs=d.blogs||[];const counts={draft:0,pending:0,published:0,scheduled:0,archived:0};blogs.forEach(b=>counts[b.status]++);stats.innerHTML='<div class="cms-card"><small>Total blogs</small><strong>'+blogs.length+'</strong></div>'+Object.entries(counts).map(([k,v])=>'<div class="cms-card"><small>'+k+'</small><strong>'+v+'</strong></div>').join('');table.innerHTML=blogs.length?'<table class="cms-table"><thead><tr><th>Title</th><th>Status</th><th>Category</th><th>Author</th><th>Keyword</th><th>Updated</th><th>Actions</th></tr></thead><tbody>'+blogs.map(b=>'<tr><td><strong>'+esc(b.title)+'</strong><br><small>/blog/'+esc(b.slug)+'</small></td><td><span class="pill '+esc(b.status)+'">'+esc(b.status)+'</span></td><td>'+esc(b.category_names||'Uncategorised')+'</td><td>'+esc(b.author_name||'Unassigned')+'</td><td>'+esc(b.primary_keyword)+'</td><td>'+esc(b.updated_at)+'</td><td><button data-edit="'+b.id+'">Edit</button> <button data-publish="'+b.id+'">'+(b.status==='published'?'Unpublish':'Publish')+'</button> <button data-delete="'+b.id+'">Delete</button></td></tr>').join('')+'</tbody></table>':'<p>No blogs found. Create the first article.</p>';table.querySelectorAll('[data-edit]').forEach(x=>x.onclick=()=>loadBlog(blogs.find(b=>b.id==x.dataset.edit)));table.querySelectorAll('[data-publish]').forEach(x=>x.onclick=()=>api('status',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:x.dataset.publish,status:x.textContent==='Publish'?'published':'draft'})}).then(refresh));table.querySelectorAll('[data-delete]').forEach(x=>x.onclick=()=>confirm('Delete this blog permanently?')&&api('delete',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:x.dataset.delete})}).then(refresh));});}
async function loadBlog(b){const response=await api('get&id='+encodeURIComponent(b.id));b=response.blog||b;editor.classList.add('active');editorTitle.textContent='Edit blog';Object.keys(b).forEach(k=>{const el=form.elements[k];if(el)el.type==='checkbox'?el.checked=!!Number(b[k]):el.value=Array.isArray(b[k])?'':(b[k]??'')});contentEditor.innerHTML=b.content||'<p>Start writing your article here...</p>';syncContent();document.getElementById('faqItems').innerHTML='';(b.faq||[]).forEach(addFaq);validateSEO()}
function validateSEO(){const f=new FormData(form), content=f.get('content')||'', checks=[['Title',!!f.get('title')?'good':'bad'],['Meta title',(f.get('meta_title')||'').length<=60?'good':'warn'],['Meta description',(f.get('meta_description')||'').length>=120?'good':'warn'],['Primary keyword',!!f.get('primary_keyword')?'good':'bad'],['Feature image alt',!!f.get('feature_image_alt')?'good':'bad'],['H2 structure',/<h2\b/i.test(content)?'good':'warn'],['Content length',content.replace(/<[^>]+>/g,' ').trim().length>=600?'good':'warn']];seoList.innerHTML=checks.map(c=>'<li class="'+c[1]+'">'+(c[1]==='good'?'GOOD':c[1]==='warn'?'WARNING':'ERROR')+' &nbsp; '+c[0]+'</li>').join('')}
newBlog.onclick=()=>{form.reset();form.id.value='';editor.classList.add('active');editorTitle.textContent='New blog';validateSEO()};cancelEdit.onclick=()=>editor.classList.remove('active');refresh.onclick=refresh;search.oninput=refresh;status.onchange=refresh;form.oninput=validateSEO;form.onsubmit=e=>{e.preventDefault();const data=Object.fromEntries(new FormData(form));data.toc_enabled=form.toc_enabled.checked?1:0;data.lead_form_enabled=form.lead_form_enabled.checked?1:0;api('save',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)}).then(d=>{formMessage.textContent=d.success?'Saved successfully':(d.error||'Unable to save');if(d.success){editor.classList.remove('active');refresh()}})};logout.onclick=()=>fetch('blog-api.php?action=logout').then(()=>location.reload());refresh();
</script></body></html>
